// Estime le coût (centimes) d'un appel LLM à partir des tokens et des prix.
// TODO : ne compter que l'entrée sous-estime la facture — la SORTIE se paie
//        aussi, et souvent plus cher.
export function estimateCents(usage) {
  return Math.round(usage.inTokens / 1000 * usage.inPricePer1kCents);
}

